query:
UPDATE course_lessons SET content = REPLACE(content,
  '$K$:** Approach speed of the body part (typically 1600 mm/s for hand/arm).',
  '$K$:** Approach speed of the body part. Per ISO 13855: use **K = 1600 mm/s** when the calculated safety distance S ≥ 500 mm (parallel approach). If S < 500 mm, you **must** recalculate using **K = 2000 mm/s** (perpendicular/reaching approach).'
) WHERE id = 120023;

